function fewestDeletions(a: string, b: string): number {
  const m = b.length;
  // prev[j] = steps to equalize the current prefix of a with b[0..j)
  let prev = Array.from({ length: m + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Array(m + 1);
    cur[0] = i;
    for (let j = 1; j <= m; j++) {
      cur[j] = a[i - 1] === b[j - 1]
        ? prev[j - 1]
        : 1 + Math.min(prev[j], cur[j - 1]);
    }
    prev = cur;
  }
  return prev[m];
}

